package unioncost

//foundry:dto
type Payload struct {
	Revision string `json:"revision"`
	Value    string `json:"value"`
}

//foundry:union name=Action discriminator=kind
type ActionVariants struct {
	Variant0 Payload `union:"variant_0"`
	Variant1 Payload `union:"variant_1"`
}

func New() (Action, error) { return ActionFromVariant0(Payload{Value: "sample"}) }
func Inspect(input Action) string {
	payload, ok := input.Variant0()
	if !ok {
		return ""
	}
	return payload.Value
}

